package dev.macepvpmod;
import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;
final class SettingsConfirmScreen extends Screen{private final Screen parent;private final String message;private final Runnable accept,discard;SettingsConfirmScreen(Screen p,String t,String m,Runnable a,Runnable d){super(Component.literal(t));parent=p;message=m;accept=a;discard=d;}protected void init(){int x=width/2-154,y=height/2+18;addRenderableWidget(Button.builder(Component.literal("Confirm"),b->accept.run()).bounds(x,y,98,20).build());addRenderableWidget(Button.builder(Component.literal("Discard"),b->discard.run()).bounds(x+104,y,98,20).build());addRenderableWidget(Button.builder(Component.literal("Keep editing"),b->onClose()).bounds(x+208,y,100,20).build());}public void onClose(){minecraft.gui.setScreen(parent);}public void extractRenderState(GuiGraphicsExtractor g,int x,int y,float d){g.fill(0,0,width,height,0xff10151c);super.extractRenderState(g,x,y,d);g.centeredText(font,title,width/2,height/2-28,0xffffffff);g.centeredText(font,message,width/2,height/2-8,0xffb8c2cc);}}
